-- Create and select the database (MySQL / MariaDB)
CREATE DATABASE IF NOT EXISTS practice_db;
USE practice_db;

-- Practice database: online store + HR data (generated with Python Faker)
-- Works with SQLite, PostgreSQL, MySQL/MariaDB.
-- Tables: departments, employees, customers, categories, products, orders, order_items, payments, reviews

DROP TABLE IF EXISTS reviews;
DROP TABLE IF EXISTS payments;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS departments;

CREATE TABLE departments (
  department_id INTEGER PRIMARY KEY,
  name VARCHAR(50) NOT NULL,
  location VARCHAR(80)
);

CREATE TABLE employees (
  employee_id INTEGER PRIMARY KEY,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(50) NOT NULL,
  email VARCHAR(120) UNIQUE,
  hire_date DATE,
  job_title VARCHAR(80),
  salary DECIMAL(10,2),
  department_id INTEGER REFERENCES departments(department_id),
  manager_id INTEGER REFERENCES employees(employee_id)
);

CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(50) NOT NULL,
  email VARCHAR(120) UNIQUE,
  phone VARCHAR(40),
  city VARCHAR(80),
  state VARCHAR(80),
  country VARCHAR(80),
  signup_date DATE,
  birth_date DATE,
  gender VARCHAR(10),
  is_active INTEGER DEFAULT 1
);

CREATE TABLE categories (
  category_id INTEGER PRIMARY KEY,
  name VARCHAR(50) NOT NULL
);

CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  category_id INTEGER REFERENCES categories(category_id),
  price DECIMAL(10,2),
  cost DECIMAL(10,2),
  stock_quantity INTEGER,
  created_at DATE
);

CREATE TABLE orders (
  order_id INTEGER PRIMARY KEY,
  customer_id INTEGER REFERENCES customers(customer_id),
  employee_id INTEGER REFERENCES employees(employee_id),
  order_date DATE,
  ship_date DATE,
  status VARCHAR(20),
  shipping_city VARCHAR(80),
  shipping_country VARCHAR(80)
);

CREATE TABLE order_items (
  order_item_id INTEGER PRIMARY KEY,
  order_id INTEGER REFERENCES orders(order_id),
  product_id INTEGER REFERENCES products(product_id),
  quantity INTEGER,
  unit_price DECIMAL(10,2),
  discount DECIMAL(4,2)
);

CREATE TABLE payments (
  payment_id INTEGER PRIMARY KEY,
  order_id INTEGER REFERENCES orders(order_id),
  payment_date DATE,
  method VARCHAR(20),
  amount DECIMAL(10,2)
);

CREATE TABLE reviews (
  review_id INTEGER PRIMARY KEY,
  product_id INTEGER REFERENCES products(product_id),
  customer_id INTEGER REFERENCES customers(customer_id),
  rating INTEGER,
  comment VARCHAR(255),
  review_date DATE
);































































































CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_items_order ON order_items(order_id);
CREATE INDEX idx_items_product ON order_items(product_id);
CREATE INDEX idx_reviews_product ON reviews(product_id);
